INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(36, 1, '2026-10-13 10:15:38', '2026-10-13 10:15:38', '<main>\r\n    <!-- SECTION 1 — CURRICULUM OVERVIEW -->\r\n    <section class=\"curriculum-overview\">\r\n        <div class=\"container\">\r\n\r\n            <div class=\"curriculum-heading\">\r\n                <div class=\"curriculum-label\">Curriculum Overview</div>\r\n                <h2 class=\"curriculum-title\">\r\n                    Academics Rooted in <span class=\"orange\">Values</span>,\r\n                    Open to the <span class=\"orange\">World</span>\r\n                </h2>\r\n            </div>\r\n\r\n            <div class=\"curriculum-grid\">\r\n\r\n                <div class=\"curriculum-text\">\r\n                    <p>\r\n                        The academic programme at Shree Mahalingeshwara Vidyanikethana\r\n                        follows the <strong>NCERT-guided curriculum</strong>, delivered\r\n                        under our affiliation with <strong>NIOS (National Institute of\r\n                        Open Schooling), New Delhi</strong>. The syllabus spans\r\n                        <strong>Grade 1 through Grade 8</strong> — giving students a\r\n                        complete foundational and middle school education within a single,\r\n                        values-rooted campus.\r\n                    </p>\r\n                    <p>\r\n                        But the curriculum here is more than a list of subjects. Every\r\n                        lesson, every activity, and every school day is shaped by the\r\n                        principle of <strong>\"living in truth\"</strong> — the idea\r\n                        that knowledge must be held together with character, and that\r\n                        what a child learns in the classroom should eventually serve\r\n                        the wider community.\r\n                    </p>\r\n                    <p>\r\n                        The school draws on <strong>India\'s ancient philosophical\r\n                        traditions</strong>, its cultural legacy, and the wisdom of\r\n                        respected teachers worldwide. Students are introduced to\r\n                        lesser-known figures from Indian history, and given hands-on\r\n                        exposure to farming and the dignity of labour — so that\r\n                        learning stays connected to life, and life stays connected\r\n                        to learning. By the time a student completes\r\n                        <strong>Grade 8</strong>, they leave with a strong academic\r\n                        foundation, a formed character, and a clear sense of purpose.\r\n                    </p>\r\n\r\n                    <div class=\"curriculum-tags\">\r\n                        <span><i class=\"bi bi-building\"></i> NIOS, New Delhi</span>\r\n                        <span><i class=\"bi bi-book-half\"></i> NCERT-Guided</span>\r\n                        <span><i class=\"bi bi-flower2\"></i> \"Living in Truth\"</span>\r\n                        <span><i class=\"bi bi-globe2\"></i> Indian Heritage</span>\r\n                        <span><i class=\"bi bi-people-fill\"></i> Community Service</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"curriculum-visual\">\r\n                    <div class=\"curriculum-image-wrap\">\r\n                        <div class=\"curriculum-image-accent\"></div>\r\n                        <figure>\r\n                            <img\r\n                                src=\"http://localhost/shree-mahalingeshwara-vidyanikethana-kunjthoor/wp-content/themes/custom-theme-child/assets/images/shree-mahalingeshwara-vidyanikethana-school-curriculum.jpg\"\r\n                                alt=\"Curriculum at Shree Mahalingeshwara Vidyanikethana\"\r\n                                title=\"Academic Curriculum and Classroom Learning at Shree Mahalingeshwara Vidyanikethana\"\r\n                                class=\"curriculum-image\"\r\n                            >\r\n                            <figcaption class=\"cr-only\">\r\n                                Comprehensive academic curriculum, NCERT guidance, NIOS accreditation, and Panchangashikshan holistic education at Shree Mahalingeshwara Vidyanikethana Kunjathur.\r\n                            </figcaption>\r\n                        </figure>\r\n                    </div>\r\n\r\n                    <div class=\"curriculum-accreditation\">\r\n                        <div class=\"accreditation-box\">\r\n                            <i class=\"bi bi-building\"></i>\r\n                            <strong>NIOS, New Delhi</strong>\r\n                            <span>Affiliated Institution</span>\r\n                        </div>\r\n                        <div class=\"accreditation-box\">\r\n                            <i class=\"bi bi-patch-check-fill\"></i>\r\n                            <strong>OB0918317</strong>\r\n                            <span>Accreditation No.</span>\r\n                        </div>\r\n                        <div class=\"accreditation-box\">\r\n                            <i class=\"bi bi-mortarboard-fill\"></i>\r\n                            <strong>Grade 1 – 8</strong>\r\n                            <span>Classes Offered</span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n\r\n    <!-- SECTION 2 — ACADEMIC SUBJECTS (TWO-LEVEL CURRICULUM) -->\r\n    <section class=\"subjects-section\">\r\n        <div class=\"container\">\r\n            <div class=\"subjects-block\">\r\n\r\n                <div class=\"subjects-heading\">\r\n                    <div class=\"curriculum-label\">Academic Subjects</div>\r\n                    <h3 class=\"subjects-title\">\r\n                        What Students <span>Learn</span>\r\n                    </h3>\r\n                </div>\r\n\r\n                <div class=\"curriculum-levels\">\r\n\r\n                    <!-- CURRICULUM FOR CLASSES I TO IV -->\r\n                    <div class=\"level-card\">\r\n                        <div class=\"level-header\">\r\n                            <div class=\"level-icon\">\r\n                                <i class=\"bi bi-book\"></i>\r\n                            </div>\r\n                            <div class=\"level-header-text\">\r\n                                <span class=\"level-tag\">Primary</span>\r\n                                <h4>Classes I – IV</h4>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <div class=\"level-subjects\">\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-book-half\"></i></div>\r\n                                <div class=\"level-subject-name\">English</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-alphabet\"></i></div>\r\n                                <div class=\"level-subject-name\">Malayalam / Kannada</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-chat-quote\"></i></div>\r\n                                <div class=\"level-subject-name\">Hindi</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-calculator\"></i></div>\r\n                                <div class=\"level-subject-name\">Mathematics</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-tree\"></i></div>\r\n                                <div class=\"level-subject-name\">Environmental Studies</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-pc-display\"></i></div>\r\n                                <div class=\"level-subject-name\">Computer Education</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-palette\"></i></div>\r\n                                <div class=\"level-subject-name\">Art Education</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-lightbulb\"></i></div>\r\n                                <div class=\"level-subject-name\">Life Skills</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-heart-fill\"></i></div>\r\n                                <div class=\"level-subject-name\">Value Education</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-person-walking\"></i></div>\r\n                                <div class=\"level-subject-name\">Physical Education</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-globe2\"></i></div>\r\n                                <div class=\"level-subject-name\">General Knowledge</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-music-note-beamed\"></i></div>\r\n                                <div class=\"level-subject-name\">Music</div>\r\n                            </div>\r\n\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- CURRICULUM FOR CLASSES V TO VIII -->\r\n                    <div class=\"level-card\">\r\n                        <div class=\"level-header\">\r\n                            <div class=\"level-icon\">\r\n                                <i class=\"bi bi-mortarboard\"></i>\r\n                            </div>\r\n                            <div class=\"level-header-text\">\r\n                                <span class=\"level-tag\">Middle School</span>\r\n                                <h4>Classes V – VIII</h4>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <div class=\"level-subjects\">\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-book-half\"></i></div>\r\n                                <div class=\"level-subject-name\">English</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-chat-quote\"></i></div>\r\n                                <div class=\"level-subject-name\">Hindi</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-translate\"></i></div>\r\n                                <div class=\"level-subject-name\">\r\n                                    Third Language\r\n                                    <small>Malayalam / Kannada / Sanskrit</small>\r\n                                </div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-calculator\"></i></div>\r\n                                <div class=\"level-subject-name\">Mathematics</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-flask\"></i></div>\r\n                                <div class=\"level-subject-name\">Science</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-globe2\"></i></div>\r\n                                <div class=\"level-subject-name\">Social Science</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-heart-fill\"></i></div>\r\n                                <div class=\"level-subject-name\">Value Education</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-lightbulb\"></i></div>\r\n                                <div class=\"level-subject-name\">Life Skills</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-pc-display\"></i></div>\r\n                                <div class=\"level-subject-name\">\r\n                                    Work Experience\r\n                                    <small>Computer Science</small>\r\n                                </div>\r\n                            </div>\r\n\r\n                        </div>\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n        </div>\r\n    </section>\r\n\r\n\r\n    <!-- SECTION 3 — PANCHANGASHIKSHAN IN CURRICULUM -->\r\n    <section class=\"panchang-curriculum\">\r\n        <div class=\"container\">\r\n\r\n            <div class=\"panchang-curriculum-heading\">\r\n                <h2 class=\"panchang-curriculum-title\">\r\n                    The <span class=\"orange\">Panchangashikshan</span><br>\r\n                    Framework in Practice\r\n                </h2>\r\n                <p class=\"panchang-curriculum-sub\">\r\n                    Five streams run through every week of the academic\r\n                    calendar — from Grade 1 to Grade 8 — not as add-ons,\r\n                    but as the rhythm of the school day itself.\r\n                </p>\r\n            </div>\r\n\r\n            <div class=\"panchang-curriculum-grid\">\r\n\r\n                <div class=\"panchang-curriculum-item\">\r\n                    <div class=\"panchang-curriculum-icon\">\r\n                        <i class=\"bi bi-person-arms-up\"></i>\r\n                    </div>\r\n                    <h3>Yoga</h3>\r\n                    <p>Stillness, breath, and physical well-being.</p>\r\n                </div>\r\n\r\n                <div class=\"panchang-curriculum-item\">\r\n                    <div class=\"panchang-curriculum-icon\">\r\n                        <i class=\"bi bi-person-walking\"></i>\r\n                    </div>\r\n                    <h3>Sports</h3>\r\n                    <p>Discipline, energy, and team spirit.</p>\r\n                </div>\r\n\r\n                <div class=\"panchang-curriculum-item\">\r\n                    <div class=\"panchang-curriculum-icon\">\r\n                        <i class=\"bi bi-music-note-beamed\"></i>\r\n                    </div>\r\n                    <h3>Music</h3>\r\n                    <p>Expression, rhythm, and creative confidence.</p>\r\n                </div>\r\n\r\n                <div class=\"panchang-curriculum-item\">\r\n                    <div class=\"panchang-curriculum-icon\">\r\n                        <i class=\"bi bi-flower1\"></i>\r\n                    </div>\r\n                    <h3>Sanskrit</h3>\r\n                    <p>Heritage, language, and ancient wisdom.</p>\r\n                </div>\r\n\r\n                <div class=\"panchang-curriculum-item\">\r\n                    <div class=\"panchang-curriculum-icon\">\r\n                        <i class=\"bi bi-book-half\"></i>\r\n                    </div>\r\n                    <h3>Naithik</h3>\r\n                    <p>Moral education and inner character.</p>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n\r\n    <!-- SECTION 4 — TEACHING METHODOLOGY -->\r\n    <section class=\"methodology-section\">\r\n        <div class=\"container\">\r\n\r\n            <div class=\"methodology-heading\">\r\n                <h2 class=\"methodology-title\">\r\n                    How We <span class=\"orange\">Teach</span>\r\n                </h2>\r\n                <p class=\"methodology-sub\">\r\n                    The classroom here is a place of discovery — where the\r\n                    mind is engaged, the heart is formed, and the child is\r\n                    always at the centre, from Grade 1 through Grade 8.\r\n                </p>\r\n            </div>\r\n\r\n            <div class=\"methodology-grid\">\r\n\r\n                <div class=\"methodology-card\">\r\n                    <div class=\"methodology-card-icon\">\r\n                        <i class=\"bi bi-people-fill\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <h3>Small, Attentive Classrooms</h3>\r\n                        <p>\r\n                            Classes are kept intentionally small so that every\r\n                            child receives personal attention — and no child\r\n                            is allowed to quietly fall behind, at any grade.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"methodology-card\">\r\n                    <div class=\"methodology-card-icon\">\r\n                        <i class=\"bi bi-lightbulb\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <h3>Learning by Doing</h3>\r\n                        <p>\r\n                            Concepts are introduced through activity, observation,\r\n                            and experience — so that understanding runs deeper\r\n                            than memory, from primary years through middle school.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"methodology-card\">\r\n                    <div class=\"methodology-card-icon\">\r\n                        <i class=\"bi bi-flower2\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <h3>Meditation Before Lessons</h3>\r\n                        <p>\r\n                            The school day begins with quiet meditation — a\r\n                            practice that settles the mind and prepares the\r\n                            child for focused learning, at every age.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"methodology-card\">\r\n                    <div class=\"methodology-card-icon\">\r\n                        <i class=\"bi bi-person-heart\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <h3>Teachers as Mentors</h3>\r\n                        <p>\r\n                            Our teachers carry the kind of freedom a mother has —\r\n                            the freedom to nurture, to correct gently, and to\r\n                            guide each child with patience across the years.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"methodology-card\">\r\n                    <div class=\"methodology-card-icon\">\r\n                        <i class=\"bi bi-globe2\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <h3>Rooted in Indian Heritage</h3>\r\n                        <p>\r\n                            The curriculum draws on India\'s ancient philosophical\r\n                            traditions, its cultural legacy, and the lives of\r\n                            lesser-known figures from Indian history.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"methodology-card\">\r\n                    <div class=\"methodology-card-icon\">\r\n                        <i class=\"bi bi-hand-index-thumb\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <h3>Dignity of Labour</h3>\r\n                        <p>\r\n                            Students receive hands-on exposure to farming and\r\n                            physical work — learning early that every form of\r\n                            honest effort deserves respect.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n\r\n    <!-- SECTION 5 — CLASSES & ASSESSMENT -->\r\n    <section class=\"classes-section\">\r\n        <div class=\"container\">\r\n\r\n            <div class=\"classes-heading\">\r\n                <h2 class=\"classes-title\">\r\n                    Classes &amp; <span class=\"orange\">Assessment</span>\r\n                </h2>\r\n                <p class=\"classes-sub\">\r\n                    A complete academic journey from Grade 1 to Grade 8 —\r\n                    with evaluation that supports learning rather than\r\n                    merely measuring it.\r\n                </p>\r\n            </div>\r\n\r\n            <div class=\"classes-grid\">\r\n\r\n                <!-- Left card — Classes -->\r\n                <div class=\"classes-card\">\r\n                    <div class=\"classes-card-icon\">\r\n                        <i class=\"bi bi-mortarboard-fill\"></i>\r\n                    </div>\r\n                    <h3>Classes Offered (Grade 1 – 8)</h3>\r\n                    <p>\r\n                        The school offers a continuous, structured programme\r\n                        from <strong>Grade 1 through Grade 8</strong>, following\r\n                        the NCERT-guided curriculum under NIOS affiliation.\r\n                        Admissions are open every January for the academic\r\n                        session beginning in June.\r\n                    </p>\r\n\r\n                    <div class=\"classes-list\">\r\n\r\n                        <div class=\"classes-list-item\">\r\n                            <div class=\"classes-list-num\">1–4</div>\r\n                            <div class=\"classes-list-body\">\r\n                                <strong>Primary Years</strong>\r\n                                <span>Joyful learning — language, numeracy, environmental studies, and early habits of curiosity.</span>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <div class=\"classes-list-item\">\r\n                            <div class=\"classes-list-num\">5–8</div>\r\n                            <div class=\"classes-list-body\">\r\n                                <strong>Middle School</strong>\r\n                                <span>Deeper concepts in science, mathematics, and social science — with growing independence.</span>\r\n                            </div>\r\n                        </div>\r\n\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Right card — Assessment -->\r\n                <div class=\"classes-card\">\r\n                    <div class=\"classes-card-icon\">\r\n                        <i class=\"bi bi-clipboard-check\"></i>\r\n                    </div>\r\n                    <h3>Examination &amp; Evaluation</h3>\r\n                    <p>\r\n                        Evaluation at the school is <strong>continuous and\r\n                        supportive</strong> — designed to identify where a child\r\n                        needs help, and to celebrate where a child excels. It\r\n                        is never used to rank or compare, but to guide.\r\n                    </p>\r\n                    <p>\r\n                        Assessment includes <strong>periodic written tests,\r\n                        oral evaluations, project work, and classroom\r\n                        participation</strong>. Equal weight is given to a\r\n                        student\'s progress in yoga, sports, music, and\r\n                        character formation — because a report card should\r\n                        reflect the whole child, not just the marks.\r\n                    </p>\r\n                    <p>\r\n                        In <strong>Grade 6, 7, and 8</strong>, students are\r\n                        prepared with structured revision, practice tests, and\r\n                        one-to-one mentoring — building a strong academic base\r\n                        for higher studies. Parents receive regular feedback\r\n                        through <strong>parent-teacher meetings</strong> and\r\n                        written progress reports, so that school and home\r\n                        can work together in the child\'s interest.\r\n                    </p>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n\r\n    <!-- SECTION 6 — CO-CURRICULAR ACTIVITIES -->\r\n    <section class=\"cocurricular-section\">\r\n        <div class=\"container\">\r\n\r\n            <div class=\"cocurricular-heading\">\r\n                <h2 class=\"cocurricular-title\">\r\n                    Co-Curricular <span class=\"orange\">Activities</span>\r\n                </h2>\r\n                <p class=\"cocurricular-sub\">\r\n                    Learning does not stop at the classroom door. Every child —\r\n                    from Grade 1 to Grade 8 — is encouraged to explore,\r\n                    create, and grow beyond books.\r\n                </p>\r\n            </div>\r\n\r\n            <div class=\"cocurricular-grid\">\r\n\r\n                <div class=\"cocurricular-item\">\r\n                    <div class=\"cocurricular-icon\">\r\n                        <i class=\"bi bi-person-arms-up\"></i>\r\n                    </div>\r\n                    <div class=\"cocurricular-body\">\r\n                        <strong>Yoga &amp; Meditation</strong>\r\n                        <span>Daily practice for physical and mental well-being.</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"cocurricular-item\">\r\n                    <div class=\"cocurricular-icon\">\r\n                        <i class=\"bi bi-music-note-beamed\"></i>\r\n                    </div>\r\n                    <div class=\"cocurricular-body\">\r\n                        <strong>Music &amp; Classical Arts</strong>\r\n                        <span>Vocal, instrumental, and classical music training.</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"cocurricular-item\">\r\n                    <div class=\"cocurricular-icon\">\r\n                        <i class=\"bi bi-flower1\"></i>\r\n                    </div>\r\n                    <div class=\"cocurricular-body\">\r\n                        <strong>Bharatanatyam</strong>\r\n                        <span>Classical dance as a form of cultural expression.</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"cocurricular-item\">\r\n                    <div class=\"cocurricular-icon\">\r\n                        <i class=\"bi bi-hand-index-thumb\"></i>\r\n                    </div>\r\n                    <div class=\"cocurricular-body\">\r\n                        <strong>Karate</strong>\r\n                        <span>Self-defence, discipline, and physical confidence.</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"cocurricular-item\">\r\n                    <div class=\"cocurricular-icon\">\r\n                        <i class=\"bi bi-palette\"></i>\r\n                    </div>\r\n                    <div class=\"cocurricular-body\">\r\n                        <strong>Craft &amp; Art</strong>\r\n                        <span>Creativity, imagination, and hands-on skill.</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"cocurricular-item\">\r\n                    <div class=\"cocurricular-icon\">\r\n                        <i class=\"bi bi-trophy-fill\"></i>\r\n                    </div>\r\n                    <div class=\"cocurricular-body\">\r\n                        <strong>Sports &amp; Athletics</strong>\r\n                        <span>Team spirit, fitness, and healthy competition.</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"cocurricular-item\">\r\n                    <div class=\"cocurricular-icon\">\r\n                        <i class=\"bi bi-tree\"></i>\r\n                    </div>\r\n                    <div class=\"cocurricular-body\">\r\n                        <strong>Farming Exposure</strong>\r\n                        <span>Hands-on contact with the dignity of labour.</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"cocurricular-item\">\r\n                    <div class=\"cocurricular-icon\">\r\n                        <i class=\"bi bi-book-half\"></i>\r\n                    </div>\r\n                    <div class=\"cocurricular-body\">\r\n                        <strong>Sanskrit &amp; Heritage</strong>\r\n                        <span>Cultural roots and ancient wisdom.</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"cocurricular-item\">\r\n                    <div class=\"cocurricular-icon\">\r\n                        <i class=\"bi bi-people-fill\"></i>\r\n                    </div>\r\n                    <div class=\"cocurricular-body\">\r\n                        <strong>Community Service</strong>\r\n                        <span>Learning to serve the school, the village, and the world.</span>\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n\r\n    <!-- SECTION 7 — CLOSING QUOTE -->\r\n    <section class=\"curriculum-closing\">\r\n        <div class=\"container\">\r\n            <p>\r\n                Eight years of learning — from the first alphabet in Grade 1\r\n                to the completion of middle school in Grade 8 — designed not\r\n                only to produce good students, but to shape good human\r\n                beings who serve their community, their country, and\r\n                humanity as a whole.\r\n            </p>\r\n            <div class=\"closing-note\">\r\n                Every Child Matters\r\n            </div>\r\n        </div>\r\n    </section>\r\n\r\n</main>', 'Curriculum', '', 'publish', 'closed', 'closed', '', 'curriculum', '', '', '2026-10-14 10:27:59', '2026-10-14 10:27:59', '', 0, 'http://localhost/shree-mahalingeshwara-vidyanikethana-kunjthoor/?page_id=36', 0, 'page', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(37, 1, '2026-10-13 10:15:38', '2026-10-13 10:15:38', '<main>\r\n\r\n    <!-- BANNER -->\r\n    <section class=\"page-banner\">\r\n        <div class=\"container\">\r\n\r\n            <div class=\"page-banner-inner\">\r\n\r\n                <div class=\"page-banner-text\">\r\n                    <div class=\"page-banner-crumb\">\r\n                        <a href=\"index.html\">Home</a>\r\n                        <i class=\"bi bi-chevron-right\"></i>\r\n                        <span>Academics</span>\r\n                        <i class=\"bi bi-chevron-right\"></i>\r\n                        <span class=\"current\">Curriculum</span>\r\n                    </div>\r\n\r\n                    <h1>\r\n                        A Curriculum for<br>\r\n                        the <span>Whole Child</span>\r\n                    </h1>\r\n                    <p>\r\n                        NCERT-guided academics from Grade 1 to Grade 8,\r\n                        woven together with the five streams of\r\n                        Panchangashikshan — so that what a child learns\r\n                        becomes what a child lives.\r\n                    </p>\r\n\r\n                    <div class=\"page-banner-facts\">\r\n                        <span><i class=\"bi bi-building\"></i> NIOS Affiliated</span>\r\n                        <span><i class=\"bi bi-book-half\"></i> NCERT-Guided</span>\r\n                        <span><i class=\"bi bi-mortarboard-fill\"></i> Grades 1 – 8</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"page-banner-visual\">\r\n                    <div class=\"banner-quote-card\">\r\n\r\n                        <div class=\"banner-quote-mark\">\r\n                            <i class=\"bi bi-quote\"></i>\r\n                        </div>\r\n\r\n                        <p class=\"banner-quote-text\">\r\n                            Education that shapes the mind,\r\n                            forms the character, and <em>serves the community</em>.\r\n                        </p>\r\n\r\n                        <div class=\"banner-quote-note\">\r\n                            Our Academic Philosophy\r\n                        </div>\r\n\r\n                        <div class=\"banner-quote-icons\">\r\n                            <span><i class=\"bi bi-flower2\"></i> Meditation</span>\r\n                            <span><i class=\"bi bi-globe2\"></i> Culture</span>\r\n                            <span><i class=\"bi bi-heart-fill\"></i> Values</span>\r\n                        </div>\r\n\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n\r\n    <!-- SECTION 1 — CURRICULUM OVERVIEW -->\r\n    <section class=\"curriculum-overview\">\r\n        <div class=\"container\">\r\n\r\n            <div class=\"curriculum-heading\">\r\n                <div class=\"curriculum-label\">Curriculum Overview</div>\r\n                <h2 class=\"curriculum-title\">\r\n                    Academics Rooted in <span class=\"orange\">Values</span>,\r\n                    Open to the <span class=\"orange\">World</span>\r\n                </h2>\r\n            </div>\r\n\r\n            <div class=\"curriculum-grid\">\r\n\r\n                <div class=\"curriculum-text\">\r\n                    <p>\r\n                        The academic programme at Shree Mahalingeshwara Vidyanikethana\r\n                        follows the <strong>NCERT-guided curriculum</strong>, delivered\r\n                        under our affiliation with <strong>NIOS (National Institute of\r\n                        Open Schooling), New Delhi</strong>. The syllabus spans\r\n                        <strong>Grade 1 through Grade 8</strong> — giving students a\r\n                        complete foundational and middle school education within a single,\r\n                        values-rooted campus.\r\n                    </p>\r\n                    <p>\r\n                        But the curriculum here is more than a list of subjects. Every\r\n                        lesson, every activity, and every school day is shaped by the\r\n                        principle of <strong>\"living in truth\"</strong> — the idea\r\n                        that knowledge must be held together with character, and that\r\n                        what a child learns in the classroom should eventually serve\r\n                        the wider community.\r\n                    </p>\r\n                    <p>\r\n                        The school draws on <strong>India\'s ancient philosophical\r\n                        traditions</strong>, its cultural legacy, and the wisdom of\r\n                        respected teachers worldwide. Students are introduced to\r\n                        lesser-known figures from Indian history, and given hands-on\r\n                        exposure to farming and the dignity of labour — so that\r\n                        learning stays connected to life, and life stays connected\r\n                        to learning. By the time a student completes\r\n                        <strong>Grade 8</strong>, they leave with a strong academic\r\n                        foundation, a formed character, and a clear sense of purpose.\r\n                    </p>\r\n\r\n                    <div class=\"curriculum-tags\">\r\n                        <span><i class=\"bi bi-building\"></i> NIOS, New Delhi</span>\r\n                        <span><i class=\"bi bi-book-half\"></i> NCERT-Guided</span>\r\n                        <span><i class=\"bi bi-flower2\"></i> \"Living in Truth\"</span>\r\n                        <span><i class=\"bi bi-globe2\"></i> Indian Heritage</span>\r\n                        <span><i class=\"bi bi-people-fill\"></i> Community Service</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"curriculum-visual\">\r\n                    <div class=\"curriculum-image-wrap\">\r\n                        <div class=\"curriculum-image-accent\"></div>\r\n                        <figure>\r\n                            <img\r\n                                src=\"images/shree-mahalingeshwara-vidyanikethana-school-curriculum.jpg\"\r\n                                alt=\"Curriculum at Shree Mahalingeshwara Vidyanikethana\"\r\n                                title=\"Academic Curriculum and Classroom Learning at Shree Mahalingeshwara Vidyanikethana\"\r\n                                class=\"curriculum-image\"\r\n                            >\r\n                            <figcaption class=\"cr-only\">\r\n                                Comprehensive academic curriculum, NCERT guidance, NIOS accreditation, and Panchangashikshan holistic education at Shree Mahalingeshwara Vidyanikethana Kunjathur.\r\n                            </figcaption>\r\n                        </figure>\r\n                    </div>\r\n\r\n                    <div class=\"curriculum-accreditation\">\r\n                        <div class=\"accreditation-box\">\r\n                            <i class=\"bi bi-building\"></i>\r\n                            <strong>NIOS, New Delhi</strong>\r\n                            <span>Affiliated Institution</span>\r\n                        </div>\r\n                        <div class=\"accreditation-box\">\r\n                            <i class=\"bi bi-patch-check-fill\"></i>\r\n                            <strong>OB0918317</strong>\r\n                            <span>Accreditation No.</span>\r\n                        </div>\r\n                        <div class=\"accreditation-box\">\r\n                            <i class=\"bi bi-mortarboard-fill\"></i>\r\n                            <strong>Grade 1 – 8</strong>\r\n                            <span>Classes Offered</span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n\r\n    <!-- SECTION 2 — ACADEMIC SUBJECTS (TWO-LEVEL CURRICULUM) -->\r\n    <section class=\"subjects-section\">\r\n        <div class=\"container\">\r\n            <div class=\"subjects-block\">\r\n\r\n                <div class=\"subjects-heading\">\r\n                    <div class=\"curriculum-label\">Academic Subjects</div>\r\n                    <h3 class=\"subjects-title\">\r\n                        What Students <span>Learn</span>\r\n                    </h3>\r\n                </div>\r\n\r\n                <div class=\"curriculum-levels\">\r\n\r\n                    <!-- CURRICULUM FOR CLASSES I TO IV -->\r\n                    <div class=\"level-card\">\r\n                        <div class=\"level-header\">\r\n                            <div class=\"level-icon\">\r\n                                <i class=\"bi bi-book\"></i>\r\n                            </div>\r\n                            <div class=\"level-header-text\">\r\n                                <span class=\"level-tag\">Primary</span>\r\n                                <h4>Classes I – IV</h4>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <div class=\"level-subjects\">\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-book-half\"></i></div>\r\n                                <div class=\"level-subject-name\">English</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-alphabet\"></i></div>\r\n                                <div class=\"level-subject-name\">Malayalam / Kannada</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-chat-quote\"></i></div>\r\n                                <div class=\"level-subject-name\">Hindi</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-calculator\"></i></div>\r\n                                <div class=\"level-subject-name\">Mathematics</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-tree\"></i></div>\r\n                                <div class=\"level-subject-name\">Environmental Studies</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-pc-display\"></i></div>\r\n                                <div class=\"level-subject-name\">Computer Education</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-palette\"></i></div>\r\n                                <div class=\"level-subject-name\">Art Education</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-lightbulb\"></i></div>\r\n                                <div class=\"level-subject-name\">Life Skills</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-heart-fill\"></i></div>\r\n                                <div class=\"level-subject-name\">Value Education</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-person-walking\"></i></div>\r\n                                <div class=\"level-subject-name\">Physical Education</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-globe2\"></i></div>\r\n                                <div class=\"level-subject-name\">General Knowledge</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-music-note-beamed\"></i></div>\r\n                                <div class=\"level-subject-name\">Music</div>\r\n                            </div>\r\n\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- CURRICULUM FOR CLASSES V TO VIII -->\r\n                    <div class=\"level-card\">\r\n                        <div class=\"level-header\">\r\n                            <div class=\"level-icon\">\r\n                                <i class=\"bi bi-mortarboard\"></i>\r\n                            </div>\r\n                            <div class=\"level-header-text\">\r\n                                <span class=\"level-tag\">Middle School</span>\r\n                                <h4>Classes V – VIII</h4>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <div class=\"level-subjects\">\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-book-half\"></i></div>\r\n                                <div class=\"level-subject-name\">English</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-chat-quote\"></i></div>\r\n                                <div class=\"level-subject-name\">Hindi</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-translate\"></i></div>\r\n                                <div class=\"level-subject-name\">\r\n                                    Third Language\r\n                                    <small>Malayalam / Kannada / Sanskrit</small>\r\n                                </div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-calculator\"></i></div>\r\n                                <div class=\"level-subject-name\">Mathematics</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-flask\"></i></div>\r\n                                <div class=\"level-subject-name\">Science</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-globe2\"></i></div>\r\n                                <div class=\"level-subject-name\">Social Science</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-heart-fill\"></i></div>\r\n                                <div class=\"level-subject-name\">Value Education</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-lightbulb\"></i></div>\r\n                                <div class=\"level-subject-name\">Life Skills</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-pc-display\"></i></div>\r\n                                <div class=\"level-subject-name\">\r\n                                    Work Experience\r\n                                    <small>Computer Science</small>\r\n                                </div>\r\n                            </div>\r\n\r\n                        </div>\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n        </div>\r\n    </section>\r\n\r\n\r\n    <!-- SECTION 3 — PANCHANGASHIKSHAN IN CURRICULUM -->\r\n    <section class=\"panchang-curriculum\">\r\n        <div class=\"container\">\r\n\r\n            <div class=\"panchang-curriculum-heading\">\r\n                <h2 class=\"panchang-curriculum-title\">\r\n                    The <span class=\"orange\">Panchangashikshan</span><br>\r\n                    Framework in Practice\r\n                </h2>\r\n                <p class=\"panchang-curriculum-sub\">\r\n                    Five streams run through every week of the academic\r\n                    calendar — from Grade 1 to Grade 8 — not as add-ons,\r\n                    but as the rhythm of the school day itself.\r\n                </p>\r\n            </div>\r\n\r\n            <div class=\"panchang-curriculum-grid\">\r\n\r\n                <div class=\"panchang-curriculum-item\">\r\n                    <div class=\"panchang-curriculum-icon\">\r\n                        <i class=\"bi bi-person-arms-up\"></i>\r\n                    </div>\r\n                    <h3>Yoga</h3>\r\n                    <p>Stillness, breath, and physical well-being.</p>\r\n                </div>\r\n\r\n                <div class=\"panchang-curriculum-item\">\r\n                    <div class=\"panchang-curriculum-icon\">\r\n                        <i class=\"bi bi-person-walking\"></i>\r\n                    </div>\r\n                    <h3>Sports</h3>\r\n                    <p>Discipline, energy, and team spirit.</p>\r\n                </div>\r\n\r\n                <div class=\"panchang-curriculum-item\">\r\n                    <div class=\"panchang-curriculum-icon\">\r\n                        <i class=\"bi bi-music-note-beamed\"></i>\r\n                    </div>\r\n                    <h3>Music</h3>\r\n                    <p>Expression, rhythm, and creative confidence.</p>\r\n                </div>\r\n\r\n                <div class=\"panchang-curriculum-item\">\r\n                    <div class=\"panchang-curriculum-icon\">\r\n                        <i class=\"bi bi-flower1\"></i>\r\n                    </div>\r\n                    <h3>Sanskrit</h3>\r\n                    <p>Heritage, language, and ancient wisdom.</p>\r\n                </div>\r\n\r\n                <div class=\"panchang-curriculum-item\">\r\n                    <div class=\"panchang-curriculum-icon\">\r\n                        <i class=\"bi bi-book-half\"></i>\r\n                    </div>\r\n                    <h3>Naithik</h3>\r\n                    <p>Moral education and inner character.</p>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n\r\n    <!-- SECTION 4 — TEACHING METHODOLOGY -->\r\n    <section class=\"methodology-section\">\r\n        <div class=\"container\">\r\n\r\n            <div class=\"methodology-heading\">\r\n                <h2 class=\"methodology-title\">\r\n                    How We <span class=\"orange\">Teach</span>\r\n                </h2>\r\n                <p class=\"methodology-sub\">\r\n                    The classroom here is a place of discovery — where the\r\n                    mind is engaged, the heart is formed, and the child is\r\n                    always at the centre, from Grade 1 through Grade 8.\r\n                </p>\r\n            </div>\r\n\r\n            <div class=\"methodology-grid\">\r\n\r\n                <div class=\"methodology-card\">\r\n                    <div class=\"methodology-card-icon\">\r\n                        <i class=\"bi bi-people-fill\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <h3>Small, Attentive Classrooms</h3>\r\n                        <p>\r\n                            Classes are kept intentionally small so that every\r\n                            child receives personal attention — and no child\r\n                            is allowed to quietly fall behind, at any grade.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"methodology-card\">\r\n                    <div class=\"methodology-card-icon\">\r\n                        <i class=\"bi bi-lightbulb\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <h3>Learning by Doing</h3>\r\n                        <p>\r\n                            Concepts are introduced through activity, observation,\r\n                            and experience — so that understanding runs deeper\r\n                            than memory, from primary years through middle school.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"methodology-card\">\r\n                    <div class=\"methodology-card-icon\">\r\n                        <i class=\"bi bi-flower2\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <h3>Meditation Before Lessons</h3>\r\n                        <p>\r\n                            The school day begins with quiet meditation — a\r\n                            practice that settles the mind and prepares the\r\n                            child for focused learning, at every age.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"methodology-card\">\r\n                    <div class=\"methodology-card-icon\">\r\n                        <i class=\"bi bi-person-heart\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <h3>Teachers as Mentors</h3>\r\n                        <p>\r\n                            Our teachers carry the kind of freedom a mother has —\r\n                            the freedom to nurture, to correct gently, and to\r\n                            guide each child with patience across the years.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"methodology-card\">\r\n                    <div class=\"methodology-card-icon\">\r\n                        <i class=\"bi bi-globe2\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <h3>Rooted in Indian Heritage</h3>\r\n                        <p>\r\n                            The curriculum draws on India\'s ancient philosophical\r\n                            traditions, its cultural legacy, and the lives of\r\n                            lesser-known figures from Indian history.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"methodology-card\">\r\n                    <div class=\"methodology-card-icon\">\r\n                        <i class=\"bi bi-hand-index-thumb\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <h3>Dignity of Labour</h3>\r\n                        <p>\r\n                            Students receive hands-on exposure to farming and\r\n                            physical work — learning early that every form of\r\n                            honest effort deserves respect.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n\r\n    <!-- SECTION 5 — CLASSES & ASSESSMENT -->\r\n    <section class=\"classes-section\">\r\n        <div class=\"container\">\r\n\r\n            <div class=\"classes-heading\">\r\n                <h2 class=\"classes-title\">\r\n                    Classes &amp; <span class=\"orange\">Assessment</span>\r\n                </h2>\r\n                <p class=\"classes-sub\">\r\n                    A complete academic journey from Grade 1 to Grade 8 —\r\n                    with evaluation that supports learning rather than\r\n                    merely measuring it.\r\n                </p>\r\n            </div>\r\n\r\n            <div class=\"classes-grid\">\r\n\r\n                <!-- Left card — Classes -->\r\n                <div class=\"classes-card\">\r\n                    <div class=\"classes-card-icon\">\r\n                        <i class=\"bi bi-mortarboard-fill\"></i>\r\n                    </div>\r\n                    <h3>Classes Offered (Grade 1 – 8)</h3>\r\n                    <p>\r\n                        The school offers a continuous, structured programme\r\n                        from <strong>Grade 1 through Grade 8</strong>, following\r\n                        the NCERT-guided curriculum under NIOS affiliation.\r\n                        Admissions are open every January for the academic\r\n                        session beginning in June.\r\n                    </p>\r\n\r\n                    <div class=\"classes-list\">\r\n\r\n                        <div class=\"classes-list-item\">\r\n                            <div class=\"classes-list-num\">1–4</div>\r\n                            <div class=\"classes-list-body\">\r\n                                <strong>Primary Years</strong>\r\n                                <span>Joyful learning — language, numeracy, environmental studies, and early habits of curiosity.</span>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <div class=\"classes-list-item\">\r\n                            <div class=\"classes-list-num\">5–8</div>\r\n                            <div class=\"classes-list-body\">\r\n                                <strong>Middle School</strong>\r\n                                <span>Deeper concepts in science, mathematics, and social science — with growing independence.</span>\r\n                            </div>\r\n                        </div>\r\n\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Right card — Assessment -->\r\n                <div class=\"classes-card\">\r\n                    <div class=\"classes-card-icon\">\r\n                        <i class=\"bi bi-clipboard-check\"></i>\r\n                    </div>\r\n                    <h3>Examination &amp; Evaluation</h3>\r\n                    <p>\r\n                        Evaluation at the school is <strong>continuous and\r\n                        supportive</strong> — designed to identify where a child\r\n                        needs help, and to celebrate where a child excels. It\r\n                        is never used to rank or compare, but to guide.\r\n                    </p>\r\n                    <p>\r\n                        Assessment includes <strong>periodic written tests,\r\n                        oral evaluations, project work, and classroom\r\n                        participation</strong>. Equal weight is given to a\r\n                        student\'s progress in yoga, sports, music, and\r\n                        character formation — because a report card should\r\n                        reflect the whole child, not just the marks.\r\n                    </p>\r\n                    <p>\r\n                        In <strong>Grade 6, 7, and 8</strong>, students are\r\n                        prepared with structured revision, practice tests, and\r\n                        one-to-one mentoring — building a strong academic base\r\n                        for higher studies. Parents receive regular feedback\r\n                        through <strong>parent-teacher meetings</strong> and\r\n                        written progress reports, so that school and home\r\n                        can work together in the child\'s interest.\r\n                    </p>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n\r\n    <!-- SECTION 6 — CO-CURRICULAR ACTIVITIES -->\r\n    <section class=\"cocurricular-section\">\r\n        <div class=\"container\">\r\n\r\n            <div class=\"cocurricular-heading\">\r\n                <h2 class=\"cocurricular-title\">\r\n                    Co-Curricular <span class=\"orange\">Activities</span>\r\n                </h2>\r\n                <p class=\"cocurricular-sub\">\r\n                    Learning does not stop at the classroom door. Every child —\r\n                    from Grade 1 to Grade 8 — is encouraged to explore,\r\n                    create, and grow beyond books.\r\n                </p>\r\n            </div>\r\n\r\n            <div class=\"cocurricular-grid\">\r\n\r\n                <div class=\"cocurricular-item\">\r\n                    <div class=\"cocurricular-icon\">\r\n                        <i class=\"bi bi-person-arms-up\"></i>\r\n                    </div>\r\n                    <div class=\"cocurricular-body\">\r\n                        <strong>Yoga &amp; Meditation</strong>\r\n                        <span>Daily practice for physical and mental well-being.</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"cocurricular-item\">\r\n                    <div class=\"cocurricular-icon\">\r\n                        <i class=\"bi bi-music-note-beamed\"></i>\r\n                    </div>\r\n                    <div class=\"cocurricular-body\">\r\n                        <strong>Music &amp; Classical Arts</strong>\r\n                        <span>Vocal, instrumental, and classical music training.</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"cocurricular-item\">\r\n                    <div class=\"cocurricular-icon\">\r\n                        <i class=\"bi bi-flower1\"></i>\r\n                    </div>\r\n                    <div class=\"cocurricular-body\">\r\n                        <strong>Bharatanatyam</strong>\r\n                        <span>Classical dance as a form of cultural expression.</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"cocurricular-item\">\r\n                    <div class=\"cocurricular-icon\">\r\n                        <i class=\"bi bi-hand-index-thumb\"></i>\r\n                    </div>\r\n                    <div class=\"cocurricular-body\">\r\n                        <strong>Karate</strong>\r\n                        <span>Self-defence, discipline, and physical confidence.</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"cocurricular-item\">\r\n                    <div class=\"cocurricular-icon\">\r\n                        <i class=\"bi bi-palette\"></i>\r\n                    </div>\r\n                    <div class=\"cocurricular-body\">\r\n                        <strong>Craft &amp; Art</strong>\r\n                        <span>Creativity, imagination, and hands-on skill.</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"cocurricular-item\">\r\n                    <div class=\"cocurricular-icon\">\r\n                        <i class=\"bi bi-trophy-fill\"></i>\r\n                    </div>\r\n                    <div class=\"cocurricular-body\">\r\n                        <strong>Sports &amp; Athletics</strong>\r\n                        <span>Team spirit, fitness, and healthy competition.</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"cocurricular-item\">\r\n                    <div class=\"cocurricular-icon\">\r\n                        <i class=\"bi bi-tree\"></i>\r\n                    </div>\r\n                    <div class=\"cocurricular-body\">\r\n                        <strong>Farming Exposure</strong>\r\n                        <span>Hands-on contact with the dignity of labour.</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"cocurricular-item\">\r\n                    <div class=\"cocurricular-icon\">\r\n                        <i class=\"bi bi-book-half\"></i>\r\n                    </div>\r\n                    <div class=\"cocurricular-body\">\r\n                        <strong>Sanskrit &amp; Heritage</strong>\r\n                        <span>Cultural roots and ancient wisdom.</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"cocurricular-item\">\r\n                    <div class=\"cocurricular-icon\">\r\n                        <i class=\"bi bi-people-fill\"></i>\r\n                    </div>\r\n                    <div class=\"cocurricular-body\">\r\n                        <strong>Community Service</strong>\r\n                        <span>Learning to serve the school, the village, and the world.</span>\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n\r\n    <!-- SECTION 7 — CLOSING QUOTE -->\r\n    <section class=\"curriculum-closing\">\r\n        <div class=\"container\">\r\n            <p>\r\n                Eight years of learning — from the first alphabet in Grade 1\r\n                to the completion of middle school in Grade 8 — designed not\r\n                only to produce good students, but to shape good human\r\n                beings who serve their community, their country, and\r\n                humanity as a whole.\r\n            </p>\r\n            <div class=\"closing-note\">\r\n                Every Child Matters\r\n            </div>\r\n        </div>\r\n    </section>\r\n\r\n</main>', 'Curriculum', '', 'inherit', 'closed', 'closed', '', '36-revision-v1', '', '', '2026-10-13 10:15:38', '2026-10-13 10:15:38', '', 36, 'http://localhost/shree-mahalingeshwara-vidyanikethana-kunjthoor/?p=37', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(38, 1, '2026-10-14 10:25:05', '2026-10-14 10:25:05', '<main>\n    <!-- SECTION 1 — CURRICULUM OVERVIEW -->\n    <section class=\"curriculum-overview\">\n        <div class=\"container\">\n\n            <div class=\"curriculum-heading\">\n                <div class=\"curriculum-label\">Curriculum Overview</div>\n                <h2 class=\"curriculum-title\">\n                    Academics Rooted in <span class=\"orange\">Values</span>,\n                    Open to the <span class=\"orange\">World</span>\n                </h2>\n            </div>\n\n            <div class=\"curriculum-grid\">\n\n                <div class=\"curriculum-text\">\n                    <p>\n                        The academic programme at Shree Mahalingeshwara Vidyanikethana\n                        follows the <strong>NCERT-guided curriculum</strong>, delivered\n                        under our affiliation with <strong>NIOS (National Institute of\n                        Open Schooling), New Delhi</strong>. The syllabus spans\n                        <strong>Grade 1 through Grade 8</strong> — giving students a\n                        complete foundational and middle school education within a single,\n                        values-rooted campus.\n                    </p>\n                    <p>\n                        But the curriculum here is more than a list of subjects. Every\n                        lesson, every activity, and every school day is shaped by the\n                        principle of <strong>\"living in truth\"</strong> — the idea\n                        that knowledge must be held together with character, and that\n                        what a child learns in the classroom should eventually serve\n                        the wider community.\n                    </p>\n                    <p>\n                        The school draws on <strong>India\'s ancient philosophical\n                        traditions</strong>, its cultural legacy, and the wisdom of\n                        respected teachers worldwide. Students are introduced to\n                        lesser-known figures from Indian history, and given hands-on\n                        exposure to farming and the dignity of labour — so that\n                        learning stays connected to life, and life stays connected\n                        to learning. By the time a student completes\n                        <strong>Grade 8</strong>, they leave with a strong academic\n                        foundation, a formed character, and a clear sense of purpose.\n                    </p>\n\n                    <div class=\"curriculum-tags\">\n                        <span><i class=\"bi bi-building\"></i> NIOS, New Delhi</span>\n                        <span><i class=\"bi bi-book-half\"></i> NCERT-Guided</span>\n                        <span><i class=\"bi bi-flower2\"></i> \"Living in Truth\"</span>\n                        <span><i class=\"bi bi-globe2\"></i> Indian Heritage</span>\n                        <span><i class=\"bi bi-people-fill\"></i> Community Service</span>\n                    </div>\n                </div>\n\n                <div class=\"curriculum-visual\">\n                    <div class=\"curriculum-image-wrap\">\n                        <div class=\"curriculum-image-accent\"></div>\n                        <figure>\n                            <img\n                                src=\"http://localhost/shree-mahalingeshwara-vidyanikethana-kunjthoor/wp-content/themes/custom-theme-child/assets/images/shree-mahalingeshwara-vidyanikethana-school-curriculum.jpg\"\n                                alt=\"Curriculum at Shree Mahalingeshwara Vidyanikethana\"\n                                title=\"Academic Curriculum and Classroom Learning at Shree Mahalingeshwara Vidyanikethana\"\n                                class=\"curriculum-image\"\n                            >\n                            <figcaption class=\"cr-only\">\n                                Comprehensive academic curriculum, NCERT guidance, NIOS accreditation, and Panchangashikshan holistic education at Shree Mahalingeshwara Vidyanikethana Kunjathur.\n                            </figcaption>\n                        </figure>\n                    </div>\n\n                    <div class=\"curriculum-accreditation\">\n                        <div class=\"accreditation-box\">\n                            <i class=\"bi bi-building\"></i>\n                            <strong>NIOS, New Delhi</strong>\n                            <span>Affiliated Institution</span>\n                        </div>\n                        <div class=\"accreditation-box\">\n                            <i class=\"bi bi-patch-check-fill\"></i>\n                            <strong>OB0918317</strong>\n                            <span>Accreditation No.</span>\n                        </div>\n                        <div class=\"accreditation-box\">\n                            <i class=\"bi bi-mortarboard-fill\"></i>\n                            <strong>Grade 1 – 8</strong>\n                            <span>Classes Offered</span>\n                        </div>\n                    </div>\n                </div>\n\n            </div>\n\n        </div>\n    </section>\n\n\n    <!-- SECTION 2 — ACADEMIC SUBJECTS (TWO-LEVEL CURRICULUM) -->\n    <section class=\"subjects-section\">\n        <div class=\"container\">\n            <div class=\"subjects-block\">\n\n                <div class=\"subjects-heading\">\n                    <div class=\"curriculum-label\">Academic Subjects</div>\n                    <h3 class=\"subjects-title\">\n                        What Students <span>Learn</span>\n                    </h3>\n                </div>\n\n                <div class=\"curriculum-levels\">\n\n                    <!-- CURRICULUM FOR CLASSES I TO IV -->\n                    <div class=\"level-card\">\n                        <div class=\"level-header\">\n                            <div class=\"level-icon\">\n                                <i class=\"bi bi-book\"></i>\n                            </div>\n                            <div class=\"level-header-text\">\n                                <span class=\"level-tag\">Primary</span>\n                                <h4>Classes I – IV</h4>\n                            </div>\n                        </div>\n\n                        <div class=\"level-subjects\">\n\n                            <div class=\"level-subject-row\">\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-book-half\"></i></div>\n                                <div class=\"level-subject-name\">English</div>\n                            </div>\n\n                            <div class=\"level-subject-row\">\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-alphabet\"></i></div>\n                                <div class=\"level-subject-name\">Malayalam / Kannada</div>\n                            </div>\n\n                            <div class=\"level-subject-row\">\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-chat-quote\"></i></div>\n                                <div class=\"level-subject-name\">Hindi</div>\n                            </div>\n\n                            <div class=\"level-subject-row\">\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-calculator\"></i></div>\n                                <div class=\"level-subject-name\">Mathematics</div>\n                            </div>\n\n                            <div class=\"level-subject-row\">\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-tree\"></i></div>\n                                <div class=\"level-subject-name\">Environmental Studies</div>\n                            </div>\n\n                            <div class=\"level-subject-row\">\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-pc-display\"></i></div>\n                                <div class=\"level-subject-name\">Computer Education</div>\n                            </div>\n\n                            <div class=\"level-subject-row\">\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-palette\"></i></div>\n                                <div class=\"level-subject-name\">Art Education</div>\n                            </div>\n\n                            <div class=\"level-subject-row\">\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-lightbulb\"></i></div>\n                                <div class=\"level-subject-name\">Life Skills</div>\n                            </div>\n\n                            <div class=\"level-subject-row\">\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-heart-fill\"></i></div>\n                                <div class=\"level-subject-name\">Value Education</div>\n                            </div>\n\n                            <div class=\"level-subject-row\">\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-person-walking\"></i></div>\n                                <div class=\"level-subject-name\">Physical Education</div>\n                            </div>\n\n                            <div class=\"level-subject-row\">\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-globe2\"></i></div>\n                                <div class=\"level-subject-name\">General Knowledge</div>\n                            </div>\n\n                            <div class=\"level-subject-row\">\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-music-note-beamed\"></i></div>\n                                <div class=\"level-subject-name\">Music</div>\n                            </div>\n\n                        </div>\n                    </div>\n\n                    <!-- CURRICULUM FOR CLASSES V TO VIII -->\n                    <div class=\"level-card\">\n                        <div class=\"level-header\">\n                            <div class=\"level-icon\">\n                                <i class=\"bi bi-mortarboard\"></i>\n                            </div>\n                            <div class=\"level-header-text\">\n                                <span class=\"level-tag\">Middle School</span>\n                                <h4>Classes V – VIII</h4>\n                            </div>\n                        </div>\n\n                        <div class=\"level-subjects\">\n\n                            <div class=\"level-subject-row\">\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-book-half\"></i></div>\n                                <div class=\"level-subject-name\">English</div>\n                            </div>\n\n                            <div class=\"level-subject-row\">\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-chat-quote\"></i></div>\n                                <div class=\"level-subject-name\">Hindi</div>\n                            </div>\n\n                            <div class=\"level-subject-row\">\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-translate\"></i></div>\n                                <div class=\"level-subject-name\">\n                                    Third Language\n                                    <small>Malayalam / Kannada / Sanskrit</small>\n                                </div>\n                            </div>\n\n                            <div class=\"level-subject-row\">\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-calculator\"></i></div>\n                                <div class=\"level-subject-name\">Mathematics</div>\n                            </div>\n\n                            <div class=\"level-subject-row\">\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-flask\"></i></div>\n                                <div class=\"level-subject-name\">Science</div>\n                            </div>\n\n                            <div class=\"level-subject-row\">\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-globe2\"></i></div>\n                                <div class=\"level-subject-name\">Social Science</div>\n                            </div>\n\n                            <div class=\"level-subject-row\">\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-heart-fill\"></i></div>\n                                <div class=\"level-subject-name\">Value Education</div>\n                            </div>\n\n                            <div class=\"level-subject-row\">\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-lightbulb\"></i></div>\n                                <div class=\"level-subject-name\">Life Skills</div>\n                            </div>\n\n                            <div class=\"level-subject-row\">\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-pc-display\"></i></div>\n                                <div class=\"level-subject-name\">\n                                    Work Experience\n                                    <small>Computer Science</small>\n                                </div>\n                            </div>\n\n                        </div>\n                    </div>\n\n                </div>\n\n            </div>\n        </div>\n    </section>\n\n\n    <!-- SECTION 3 — PANCHANGASHIKSHAN IN CURRICULUM -->\n    <section class=\"panchang-curriculum\">\n        <div class=\"container\">\n\n            <div class=\"panchang-curriculum-heading\">\n                <h2 class=\"panchang-curriculum-title\">\n                    The <span class=\"orange\">Panchangashikshan</span><br>\n                    Framework in Practice\n                </h2>\n                <p class=\"panchang-curriculum-sub\">\n                    Five streams run through every week of the academic\n                    calendar — from Grade 1 to Grade 8 — not as add-ons,\n                    but as the rhythm of the school day itself.\n                </p>\n            </div>\n\n            <div class=\"panchang-curriculum-grid\">\n\n                <div class=\"panchang-curriculum-item\">\n                    <div class=\"panchang-curriculum-icon\">\n                        <i class=\"bi bi-person-arms-up\"></i>\n                    </div>\n                    <h3>Yoga</h3>\n                    <p>Stillness, breath, and physical well-being.</p>\n                </div>\n\n                <div class=\"panchang-curriculum-item\">\n                    <div class=\"panchang-curriculum-icon\">\n                        <i class=\"bi bi-person-walking\"></i>\n                    </div>\n                    <h3>Sports</h3>\n                    <p>Discipline, energy, and team spirit.</p>\n                </div>\n\n                <div class=\"panchang-curriculum-item\">\n                    <div class=\"panchang-curriculum-icon\">\n                        <i class=\"bi bi-music-note-beamed\"></i>\n                    </div>\n                    <h3>Music</h3>\n                    <p>Expression, rhythm, and creative confidence.</p>\n                </div>\n\n                <div class=\"panchang-curriculum-item\">\n                    <div class=\"panchang-curriculum-icon\">\n                        <i class=\"bi bi-flower1\"></i>\n                    </div>\n                    <h3>Sanskrit</h3>\n                    <p>Heritage, language, and ancient wisdom.</p>\n                </div>\n\n                <div class=\"panchang-curriculum-item\">\n                    <div class=\"panchang-curriculum-icon\">\n                        <i class=\"bi bi-book-half\"></i>\n                    </div>\n                    <h3>Naithik</h3>\n                    <p>Moral education and inner character.</p>\n                </div>\n\n            </div>\n\n        </div>\n    </section>\n\n\n    <!-- SECTION 4 — TEACHING METHODOLOGY -->\n    <section class=\"methodology-section\">\n        <div class=\"container\">\n\n            <div class=\"methodology-heading\">\n                <h2 class=\"methodology-title\">\n                    How We <span class=\"orange\">Teach</span>\n                </h2>\n                <p class=\"methodology-sub\">\n                    The classroom here is a place of discovery — where the\n                    mind is engaged, the heart is formed, and the child is\n                    always at the centre, from Grade 1 through Grade 8.\n                </p>\n            </div>\n\n            <div class=\"methodology-grid\">\n\n                <div class=\"methodology-card\">\n                    <div class=\"methodology-card-icon\">\n                        <i class=\"bi bi-people-fill\"></i>\n                    </div>\n                    <div>\n                        <h3>Small, Attentive Classrooms</h3>\n                        <p>\n                            Classes are kept intentionally small so that every\n                            child receives personal attention — and no child\n                            is allowed to quietly fall behind, at any grade.\n                        </p>\n                    </div>\n                </div>\n\n                <div class=\"methodology-card\">\n                    <div class=\"methodology-card-icon\">\n                        <i class=\"bi bi-lightbulb\"></i>\n                    </div>\n                    <div>\n                        <h3>Learning by Doing</h3>\n                        <p>\n                            Concepts are introduced through activity, observation,\n                            and experience — so that understanding runs deeper\n                            than memory, from primary years through middle school.\n                        </p>\n                    </div>\n                </div>\n\n                <div class=\"methodology-card\">\n                    <div class=\"methodology-card-icon\">\n                        <i class=\"bi bi-flower2\"></i>\n                    </div>\n                    <div>\n                        <h3>Meditation Before Lessons</h3>\n                        <p>\n                            The school day begins with quiet meditation — a\n                            practice that settles the mind and prepares the\n                            child for focused learning, at every age.\n                        </p>\n                    </div>\n                </div>\n\n                <div class=\"methodology-card\">\n                    <div class=\"methodology-card-icon\">\n                        <i class=\"bi bi-person-heart\"></i>\n                    </div>\n                    <div>\n                        <h3>Teachers as Mentors</h3>\n                        <p>\n                            Our teachers carry the kind of freedom a mother has —\n                            the freedom to nurture, to correct gently, and to\n                            guide each child with patience across the years.\n                        </p>\n                    </div>\n                </div>\n\n                <div class=\"methodology-card\">\n                    <div class=\"methodology-card-icon\">\n                        <i class=\"bi bi-globe2\"></i>\n                    </div>\n                    <div>\n                        <h3>Rooted in Indian Heritage</h3>\n                        <p>\n                            The curriculum draws on India\'s ancient philosophical\n                            traditions, its cultural legacy, and the lives of\n                            lesser-known figures from Indian history.\n                        </p>\n                    </div>\n                </div>\n\n                <div class=\"methodology-card\">\n                    <div class=\"methodology-card-icon\">\n                        <i class=\"bi bi-hand-index-thumb\"></i>\n                    </div>\n                    <div>\n                        <h3>Dignity of Labour</h3>\n                        <p>\n                            Students receive hands-on exposure to farming and\n                            physical work — learning early that every form of\n                            honest effort deserves respect.\n                        </p>\n                    </div>\n                </div>\n\n            </div>\n\n        </div>\n    </section>\n\n\n    <!-- SECTION 5 — CLASSES & ASSESSMENT -->\n    <section class=\"classes-section\">\n        <div class=\"container\">\n\n            <div class=\"classes-heading\">\n                <h2 class=\"classes-title\">\n                    Classes &amp; <span class=\"orange\">Assessment</span>\n                </h2>\n                <p class=\"classes-sub\">\n                    A complete academic journey from Grade 1 to Grade 8 —\n                    with evaluation that supports learning rather than\n                    merely measuring it.\n                </p>\n            </div>\n\n            <div class=\"classes-grid\">\n\n                <!-- Left card — Classes -->\n                <div class=\"classes-card\">\n                    <div class=\"classes-card-icon\">\n                        <i class=\"bi bi-mortarboard-fill\"></i>\n                    </div>\n                    <h3>Classes Offered (Grade 1 – 8)</h3>\n                    <p>\n                        The school offers a continuous, structured programme\n                        from <strong>Grade 1 through Grade 8</strong>, following\n                        the NCERT-guided curriculum under NIOS affiliation.\n                        Admissions are open every January for the academic\n                        session beginning in June.\n                    </p>\n\n                    <div class=\"classes-list\">\n\n                        <div class=\"classes-list-item\">\n                            <div class=\"classes-list-num\">1–4</div>\n                            <div class=\"classes-list-body\">\n                                <strong>Primary Years</strong>\n                                <span>Joyful learning — language, numeracy, environmental studies, and early habits of curiosity.</span>\n                            </div>\n                        </div>\n\n                        <div class=\"classes-list-item\">\n                            <div class=\"classes-list-num\">5–8</div>\n                            <div class=\"classes-list-body\">\n                                <strong>Middle School</strong>\n                                <span>Deeper concepts in science, mathematics, and social science — with growing independence.</span>\n                            </div>\n                        </div>\n\n                    </div>\n                </div>\n\n                <!-- Right card — Assessment -->\n                <div class=\"classes-card\">\n                    <div class=\"classes-card-icon\">\n                        <i class=\"bi bi-clipboard-check\"></i>\n                    </div>\n                    <h3>Examination &amp; Evaluation</h3>\n                    <p>\n                        Evaluation at the school is <strong>continuous and\n                        supportive</strong> — designed to identify where a child\n                        needs help, and to celebrate where a child excels. It\n                        is never used to rank or compare, but to guide.\n                    </p>\n                    <p>\n                        Assessment includes <strong>periodic written tests,\n                        oral evaluations, project work, and classroom\n                        participation</strong>. Equal weight is given to a\n                        student\'s progress in yoga, sports, music, and\n                        character formation — because a report card should\n                        reflect the whole child, not just the marks.\n                    </p>\n                    <p>\n                        In <strong>Grade 6, 7, and 8</strong>, students are\n                        prepared with structured revision, practice tests, and\n                        one-to-one mentoring — building a strong academic base\n                        for higher studies. Parents receive regular feedback\n                        through <strong>parent-teacher meetings</strong> and\n                        written progress reports, so that school and home\n                        can work together in the child\'s interest.\n                    </p>\n                </div>\n\n            </div>\n\n        </div>\n    </section>\n\n\n    <!-- SECTION 6 — CO-CURRICULAR ACTIVITIES -->\n    <section class=\"cocurricular-section\">\n        <div class=\"container\">\n\n            <div class=\"cocurricular-heading\">\n                <h2 class=\"cocurricular-title\">\n                    Co-Curricular <span class=\"orange\">Activities</span>\n                </h2>\n                <p class=\"cocurricular-sub\">\n                    Learning does not stop at the classroom door. Every child —\n                    from Grade 1 to Grade 8 — is encouraged to explore,\n                    create, and grow beyond books.\n                </p>\n            </div>\n\n            <div class=\"cocurricular-grid\">\n\n                <div class=\"cocurricular-item\">\n                    <div class=\"cocurricular-icon\">\n                        <i class=\"bi bi-person-arms-up\"></i>\n                    </div>\n                    <div class=\"cocurricular-body\">\n                        <strong>Yoga &amp; Meditation</strong>\n                        <span>Daily practice for physical and mental well-being.</span>\n                    </div>\n                </div>\n\n                <div class=\"cocurricular-item\">\n                    <div class=\"cocurricular-icon\">\n                        <i class=\"bi bi-music-note-beamed\"></i>\n                    </div>\n                    <div class=\"cocurricular-body\">\n                        <strong>Music &amp; Classical Arts</strong>\n                        <span>Vocal, instrumental, and classical music training.</span>\n                    </div>\n                </div>\n\n                <div class=\"cocurricular-item\">\n                    <div class=\"cocurricular-icon\">\n                        <i class=\"bi bi-flower1\"></i>\n                    </div>\n                    <div class=\"cocurricular-body\">\n                        <strong>Bharatanatyam</strong>\n                        <span>Classical dance as a form of cultural expression.</span>\n                    </div>\n                </div>\n\n                <div class=\"cocurricular-item\">\n                    <div class=\"cocurricular-icon\">\n                        <i class=\"bi bi-hand-index-thumb\"></i>\n                    </div>\n                    <div class=\"cocurricular-body\">\n                        <strong>Karate</strong>\n                        <span>Self-defence, discipline, and physical confidence.</span>\n                    </div>\n                </div>\n\n                <div class=\"cocurricular-item\">\n                    <div class=\"cocurricular-icon\">\n                        <i class=\"bi bi-palette\"></i>\n                    </div>\n                    <div class=\"cocurricular-body\">\n                        <strong>Craft &amp; Art</strong>\n                        <span>Creativity, imagination, and hands-on skill.</span>\n                    </div>\n                </div>\n\n                <div class=\"cocurricular-item\">\n                    <div class=\"cocurricular-icon\">\n                        <i class=\"bi bi-trophy-fill\"></i>\n                    </div>\n                    <div class=\"cocurricular-body\">\n                        <strong>Sports &amp; Athletics</strong>\n                        <span>Team spirit, fitness, and healthy competition.</span>\n                    </div>\n                </div>\n\n                <div class=\"cocurricular-item\">\n                    <div class=\"cocurricular-icon\">\n                        <i class=\"bi bi-tree\"></i>\n                    </div>\n                    <div class=\"cocurricular-body\">\n                        <strong>Farming Exposure</strong>\n                        <span>Hands-on contact with the dignity of labour.</span>\n                    </div>\n                </div>\n\n                <div class=\"cocurricular-item\">\n                    <div class=\"cocurricular-icon\">\n                        <i class=\"bi bi-book-half\"></i>\n                    </div>\n                    <div class=\"cocurricular-body\">\n                        <strong>Sanskrit &amp; Heritage</strong>\n                        <span>Cultural roots and ancient wisdom.</span>\n                    </div>\n                </div>\n\n                <div class=\"cocurricular-item\">\n                    <div class=\"cocurricular-icon\">\n                        <i class=\"bi bi-people-fill\"></i>\n                    </div>\n                    <div class=\"cocurricular-body\">\n                        <strong>Community Service</strong>\n                        <span>Learning to serve the school, the village, and the world.</span>\n                    </div>\n                </div>\n\n            </div>\n\n        </div>\n    </section>\n\n\n    <!-- SECTION 7 — CLOSING QUOTE -->\n    <section class=\"curriculum-closing\">\n        <div class=\"container\">\n            <p>\n                Eight years of learning — from the first alphabet in Grade 1\n                to the completion of middle school in Grade 8 — designed not\n                only to produce good students, but to shape good human\n                beings who serve their community, their country, and\n                humanity as a whole.\n            </p>\n            <div class=\"closing-note\">\n                Every Child Matters\n            </div>\n        </div>\n    </section>\n\n</main>', 'Curriculum', '', 'inherit', 'closed', 'closed', '', '36-autosave-v1', '', '', '2026-10-14 10:25:05', '2026-10-14 10:25:05', '', 36, 'http://localhost/shree-mahalingeshwara-vidyanikethana-kunjthoor/?p=38', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(39, 1, '2026-10-13 10:16:54', '2026-10-13 10:16:54', '<main>\r\n\r\n    <!-- BANNER -->\r\n    <section class=\"page-banner\">\r\n        <div class=\"container\">\r\n\r\n            <div class=\"page-banner-inner\">\r\n\r\n                <div class=\"page-banner-text\">\r\n                    <div class=\"page-banner-crumb\">\r\n                        <a href=\"index.html\">Home</a>\r\n                        <i class=\"bi bi-chevron-right\"></i>\r\n                        <span>Academics</span>\r\n                        <i class=\"bi bi-chevron-right\"></i>\r\n                        <span class=\"current\">Curriculum</span>\r\n                    </div>\r\n\r\n                    <h1>\r\n                        A Curriculum for<br>\r\n                        the <span>Whole Child</span>\r\n                    </h1>\r\n                    <p>\r\n                        NCERT-guided academics from Grade 1 to Grade 8,\r\n                        woven together with the five streams of\r\n                        Panchangashikshan — so that what a child learns\r\n                        becomes what a child lives.\r\n                    </p>\r\n\r\n                    <div class=\"page-banner-facts\">\r\n                        <span><i class=\"bi bi-building\"></i> NIOS Affiliated</span>\r\n                        <span><i class=\"bi bi-book-half\"></i> NCERT-Guided</span>\r\n                        <span><i class=\"bi bi-mortarboard-fill\"></i> Grades 1 – 8</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"page-banner-visual\">\r\n                    <div class=\"banner-quote-card\">\r\n\r\n                        <div class=\"banner-quote-mark\">\r\n                            <i class=\"bi bi-quote\"></i>\r\n                        </div>\r\n\r\n                        <p class=\"banner-quote-text\">\r\n                            Education that shapes the mind,\r\n                            forms the character, and <em>serves the community</em>.\r\n                        </p>\r\n\r\n                        <div class=\"banner-quote-note\">\r\n                            Our Academic Philosophy\r\n                        </div>\r\n\r\n                        <div class=\"banner-quote-icons\">\r\n                            <span><i class=\"bi bi-flower2\"></i> Meditation</span>\r\n                            <span><i class=\"bi bi-globe2\"></i> Culture</span>\r\n                            <span><i class=\"bi bi-heart-fill\"></i> Values</span>\r\n                        </div>\r\n\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n\r\n    <!-- SECTION 1 — CURRICULUM OVERVIEW -->\r\n    <section class=\"curriculum-overview\">\r\n        <div class=\"container\">\r\n\r\n            <div class=\"curriculum-heading\">\r\n                <div class=\"curriculum-label\">Curriculum Overview</div>\r\n                <h2 class=\"curriculum-title\">\r\n                    Academics Rooted in <span class=\"orange\">Values</span>,\r\n                    Open to the <span class=\"orange\">World</span>\r\n                </h2>\r\n            </div>\r\n\r\n            <div class=\"curriculum-grid\">\r\n\r\n                <div class=\"curriculum-text\">\r\n                    <p>\r\n                        The academic programme at Shree Mahalingeshwara Vidyanikethana\r\n                        follows the <strong>NCERT-guided curriculum</strong>, delivered\r\n                        under our affiliation with <strong>NIOS (National Institute of\r\n                        Open Schooling), New Delhi</strong>. The syllabus spans\r\n                        <strong>Grade 1 through Grade 8</strong> — giving students a\r\n                        complete foundational and middle school education within a single,\r\n                        values-rooted campus.\r\n                    </p>\r\n                    <p>\r\n                        But the curriculum here is more than a list of subjects. Every\r\n                        lesson, every activity, and every school day is shaped by the\r\n                        principle of <strong>\"living in truth\"</strong> — the idea\r\n                        that knowledge must be held together with character, and that\r\n                        what a child learns in the classroom should eventually serve\r\n                        the wider community.\r\n                    </p>\r\n                    <p>\r\n                        The school draws on <strong>India\'s ancient philosophical\r\n                        traditions</strong>, its cultural legacy, and the wisdom of\r\n                        respected teachers worldwide. Students are introduced to\r\n                        lesser-known figures from Indian history, and given hands-on\r\n                        exposure to farming and the dignity of labour — so that\r\n                        learning stays connected to life, and life stays connected\r\n                        to learning. By the time a student completes\r\n                        <strong>Grade 8</strong>, they leave with a strong academic\r\n                        foundation, a formed character, and a clear sense of purpose.\r\n                    </p>\r\n\r\n                    <div class=\"curriculum-tags\">\r\n                        <span><i class=\"bi bi-building\"></i> NIOS, New Delhi</span>\r\n                        <span><i class=\"bi bi-book-half\"></i> NCERT-Guided</span>\r\n                        <span><i class=\"bi bi-flower2\"></i> \"Living in Truth\"</span>\r\n                        <span><i class=\"bi bi-globe2\"></i> Indian Heritage</span>\r\n                        <span><i class=\"bi bi-people-fill\"></i> Community Service</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"curriculum-visual\">\r\n                    <div class=\"curriculum-image-wrap\">\r\n                        <div class=\"curriculum-image-accent\"></div>\r\n                        <figure>\r\n                            <img\r\n                                src=\"http://localhost/shree-mahalingeshwara-vidyanikethana-kunjthoor/wp-content/themes/custom-theme-child/assets/images/shree-mahalingeshwara-vidyanikethana-school-curriculum.jpg\"\r\n                                alt=\"Curriculum at Shree Mahalingeshwara Vidyanikethana\"\r\n                                title=\"Academic Curriculum and Classroom Learning at Shree Mahalingeshwara Vidyanikethana\"\r\n                                class=\"curriculum-image\"\r\n                            >\r\n                            <figcaption class=\"cr-only\">\r\n                                Comprehensive academic curriculum, NCERT guidance, NIOS accreditation, and Panchangashikshan holistic education at Shree Mahalingeshwara Vidyanikethana Kunjathur.\r\n                            </figcaption>\r\n                        </figure>\r\n                    </div>\r\n\r\n                    <div class=\"curriculum-accreditation\">\r\n                        <div class=\"accreditation-box\">\r\n                            <i class=\"bi bi-building\"></i>\r\n                            <strong>NIOS, New Delhi</strong>\r\n                            <span>Affiliated Institution</span>\r\n                        </div>\r\n                        <div class=\"accreditation-box\">\r\n                            <i class=\"bi bi-patch-check-fill\"></i>\r\n                            <strong>OB0918317</strong>\r\n                            <span>Accreditation No.</span>\r\n                        </div>\r\n                        <div class=\"accreditation-box\">\r\n                            <i class=\"bi bi-mortarboard-fill\"></i>\r\n                            <strong>Grade 1 – 8</strong>\r\n                            <span>Classes Offered</span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n\r\n    <!-- SECTION 2 — ACADEMIC SUBJECTS (TWO-LEVEL CURRICULUM) -->\r\n    <section class=\"subjects-section\">\r\n        <div class=\"container\">\r\n            <div class=\"subjects-block\">\r\n\r\n                <div class=\"subjects-heading\">\r\n                    <div class=\"curriculum-label\">Academic Subjects</div>\r\n                    <h3 class=\"subjects-title\">\r\n                        What Students <span>Learn</span>\r\n                    </h3>\r\n                </div>\r\n\r\n                <div class=\"curriculum-levels\">\r\n\r\n                    <!-- CURRICULUM FOR CLASSES I TO IV -->\r\n                    <div class=\"level-card\">\r\n                        <div class=\"level-header\">\r\n                            <div class=\"level-icon\">\r\n                                <i class=\"bi bi-book\"></i>\r\n                            </div>\r\n                            <div class=\"level-header-text\">\r\n                                <span class=\"level-tag\">Primary</span>\r\n                                <h4>Classes I – IV</h4>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <div class=\"level-subjects\">\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-book-half\"></i></div>\r\n                                <div class=\"level-subject-name\">English</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-alphabet\"></i></div>\r\n                                <div class=\"level-subject-name\">Malayalam / Kannada</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-chat-quote\"></i></div>\r\n                                <div class=\"level-subject-name\">Hindi</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-calculator\"></i></div>\r\n                                <div class=\"level-subject-name\">Mathematics</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-tree\"></i></div>\r\n                                <div class=\"level-subject-name\">Environmental Studies</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-pc-display\"></i></div>\r\n                                <div class=\"level-subject-name\">Computer Education</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-palette\"></i></div>\r\n                                <div class=\"level-subject-name\">Art Education</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-lightbulb\"></i></div>\r\n                                <div class=\"level-subject-name\">Life Skills</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-heart-fill\"></i></div>\r\n                                <div class=\"level-subject-name\">Value Education</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-person-walking\"></i></div>\r\n                                <div class=\"level-subject-name\">Physical Education</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-globe2\"></i></div>\r\n                                <div class=\"level-subject-name\">General Knowledge</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-music-note-beamed\"></i></div>\r\n                                <div class=\"level-subject-name\">Music</div>\r\n                            </div>\r\n\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- CURRICULUM FOR CLASSES V TO VIII -->\r\n                    <div class=\"level-card\">\r\n                        <div class=\"level-header\">\r\n                            <div class=\"level-icon\">\r\n                                <i class=\"bi bi-mortarboard\"></i>\r\n                            </div>\r\n                            <div class=\"level-header-text\">\r\n                                <span class=\"level-tag\">Middle School</span>\r\n                                <h4>Classes V – VIII</h4>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <div class=\"level-subjects\">\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-book-half\"></i></div>\r\n                                <div class=\"level-subject-name\">English</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-chat-quote\"></i></div>\r\n                                <div class=\"level-subject-name\">Hindi</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-translate\"></i></div>\r\n                                <div class=\"level-subject-name\">\r\n                                    Third Language\r\n                                    <small>Malayalam / Kannada / Sanskrit</small>\r\n                                </div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-calculator\"></i></div>\r\n                                <div class=\"level-subject-name\">Mathematics</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-flask\"></i></div>\r\n                                <div class=\"level-subject-name\">Science</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-globe2\"></i></div>\r\n                                <div class=\"level-subject-name\">Social Science</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-heart-fill\"></i></div>\r\n                                <div class=\"level-subject-name\">Value Education</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-lightbulb\"></i></div>\r\n                                <div class=\"level-subject-name\">Life Skills</div>\r\n                            </div>\r\n\r\n                            <div class=\"level-subject-row\">\r\n                                <div class=\"level-subject-icon\"><i class=\"bi bi-pc-display\"></i></div>\r\n                                <div class=\"level-subject-name\">\r\n                                    Work Experience\r\n                                    <small>Computer Science</small>\r\n                                </div>\r\n                            </div>\r\n\r\n                        </div>\r\n                    </div>\r\n\r\n                </div>\r\n\r\n            </div>\r\n        </div>\r\n    </section>\r\n\r\n\r\n    <!-- SECTION 3 — PANCHANGASHIKSHAN IN CURRICULUM -->\r\n    <section class=\"panchang-curriculum\">\r\n        <div class=\"container\">\r\n\r\n            <div class=\"panchang-curriculum-heading\">\r\n                <h2 class=\"panchang-curriculum-title\">\r\n                    The <span class=\"orange\">Panchangashikshan</span><br>\r\n                    Framework in Practice\r\n                </h2>\r\n                <p class=\"panchang-curriculum-sub\">\r\n                    Five streams run through every week of the academic\r\n                    calendar — from Grade 1 to Grade 8 — not as add-ons,\r\n                    but as the rhythm of the school day itself.\r\n                </p>\r\n            </div>\r\n\r\n            <div class=\"panchang-curriculum-grid\">\r\n\r\n                <div class=\"panchang-curriculum-item\">\r\n                    <div class=\"panchang-curriculum-icon\">\r\n                        <i class=\"bi bi-person-arms-up\"></i>\r\n                    </div>\r\n                    <h3>Yoga</h3>\r\n                    <p>Stillness, breath, and physical well-being.</p>\r\n                </div>\r\n\r\n                <div class=\"panchang-curriculum-item\">\r\n                    <div class=\"panchang-curriculum-icon\">\r\n                        <i class=\"bi bi-person-walking\"></i>\r\n                    </div>\r\n                    <h3>Sports</h3>\r\n                    <p>Discipline, energy, and team spirit.</p>\r\n                </div>\r\n\r\n                <div class=\"panchang-curriculum-item\">\r\n                    <div class=\"panchang-curriculum-icon\">\r\n                        <i class=\"bi bi-music-note-beamed\"></i>\r\n                    </div>\r\n                    <h3>Music</h3>\r\n                    <p>Expression, rhythm, and creative confidence.</p>\r\n                </div>\r\n\r\n                <div class=\"panchang-curriculum-item\">\r\n                    <div class=\"panchang-curriculum-icon\">\r\n                        <i class=\"bi bi-flower1\"></i>\r\n                    </div>\r\n                    <h3>Sanskrit</h3>\r\n                    <p>Heritage, language, and ancient wisdom.</p>\r\n                </div>\r\n\r\n                <div class=\"panchang-curriculum-item\">\r\n                    <div class=\"panchang-curriculum-icon\">\r\n                        <i class=\"bi bi-book-half\"></i>\r\n                    </div>\r\n                    <h3>Naithik</h3>\r\n                    <p>Moral education and inner character.</p>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n\r\n    <!-- SECTION 4 — TEACHING METHODOLOGY -->\r\n    <section class=\"methodology-section\">\r\n        <div class=\"container\">\r\n\r\n            <div class=\"methodology-heading\">\r\n                <h2 class=\"methodology-title\">\r\n                    How We <span class=\"orange\">Teach</span>\r\n                </h2>\r\n                <p class=\"methodology-sub\">\r\n                    The classroom here is a place of discovery — where the\r\n                    mind is engaged, the heart is formed, and the child is\r\n                    always at the centre, from Grade 1 through Grade 8.\r\n                </p>\r\n            </div>\r\n\r\n            <div class=\"methodology-grid\">\r\n\r\n                <div class=\"methodology-card\">\r\n                    <div class=\"methodology-card-icon\">\r\n                        <i class=\"bi bi-people-fill\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <h3>Small, Attentive Classrooms</h3>\r\n                        <p>\r\n                            Classes are kept intentionally small so that every\r\n                            child receives personal attention — and no child\r\n                            is allowed to quietly fall behind, at any grade.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"methodology-card\">\r\n                    <div class=\"methodology-card-icon\">\r\n                        <i class=\"bi bi-lightbulb\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <h3>Learning by Doing</h3>\r\n                        <p>\r\n                            Concepts are introduced through activity, observation,\r\n                            and experience — so that understanding runs deeper\r\n                            than memory, from primary years through middle school.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"methodology-card\">\r\n                    <div class=\"methodology-card-icon\">\r\n                        <i class=\"bi bi-flower2\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <h3>Meditation Before Lessons</h3>\r\n                        <p>\r\n                            The school day begins with quiet meditation — a\r\n                            practice that settles the mind and prepares the\r\n                            child for focused learning, at every age.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"methodology-card\">\r\n                    <div class=\"methodology-card-icon\">\r\n                        <i class=\"bi bi-person-heart\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <h3>Teachers as Mentors</h3>\r\n                        <p>\r\n                            Our teachers carry the kind of freedom a mother has —\r\n                            the freedom to nurture, to correct gently, and to\r\n                            guide each child with patience across the years.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"methodology-card\">\r\n                    <div class=\"methodology-card-icon\">\r\n                        <i class=\"bi bi-globe2\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <h3>Rooted in Indian Heritage</h3>\r\n                        <p>\r\n                            The curriculum draws on India\'s ancient philosophical\r\n                            traditions, its cultural legacy, and the lives of\r\n                            lesser-known figures from Indian history.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"methodology-card\">\r\n                    <div class=\"methodology-card-icon\">\r\n                        <i class=\"bi bi-hand-index-thumb\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <h3>Dignity of Labour</h3>\r\n                        <p>\r\n                            Students receive hands-on exposure to farming and\r\n                            physical work — learning early that every form of\r\n                            honest effort deserves respect.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n\r\n    <!-- SECTION 5 — CLASSES & ASSESSMENT -->\r\n    <section class=\"classes-section\">\r\n        <div class=\"container\">\r\n\r\n            <div class=\"classes-heading\">\r\n                <h2 class=\"classes-title\">\r\n                    Classes &amp; <span class=\"orange\">Assessment</span>\r\n                </h2>\r\n                <p class=\"classes-sub\">\r\n                    A complete academic journey from Grade 1 to Grade 8 —\r\n                    with evaluation that supports learning rather than\r\n                    merely measuring it.\r\n                </p>\r\n            </div>\r\n\r\n            <div class=\"classes-grid\">\r\n\r\n                <!-- Left card — Classes -->\r\n                <div class=\"classes-card\">\r\n                    <div class=\"classes-card-icon\">\r\n                        <i class=\"bi bi-mortarboard-fill\"></i>\r\n                    </div>\r\n                    <h3>Classes Offered (Grade 1 – 8)</h3>\r\n                    <p>\r\n                        The school offers a continuous, structured programme\r\n                        from <strong>Grade 1 through Grade 8</strong>, following\r\n                        the NCERT-guided curriculum under NIOS affiliation.\r\n                        Admissions are open every January for the academic\r\n                        session beginning in June.\r\n                    </p>\r\n\r\n                    <div class=\"classes-list\">\r\n\r\n                        <div class=\"classes-list-item\">\r\n                            <div class=\"classes-list-num\">1–4</div>\r\n                            <div class=\"classes-list-body\">\r\n                                <strong>Primary Years</strong>\r\n                                <span>Joyful learning — language, numeracy, environmental studies, and early habits of curiosity.</span>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <div class=\"classes-list-item\">\r\n                            <div class=\"classes-list-num\">5–8</div>\r\n                            <div class=\"classes-list-body\">\r\n                                <strong>Middle School</strong>\r\n                                <span>Deeper concepts in science, mathematics, and social science — with growing independence.</span>\r\n                            </div>\r\n                        </div>\r\n\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Right card — Assessment -->\r\n                <div class=\"classes-card\">\r\n                    <div class=\"classes-card-icon\">\r\n                        <i class=\"bi bi-clipboard-check\"></i>\r\n                    </div>\r\n                    <h3>Examination &amp; Evaluation</h3>\r\n                    <p>\r\n                        Evaluation at the school is <strong>continuous and\r\n                        supportive</strong> — designed to identify where a child\r\n                        needs help, and to celebrate where a child excels. It\r\n                        is never used to rank or compare, but to guide.\r\n                    </p>\r\n                    <p>\r\n                        Assessment includes <strong>periodic written tests,\r\n                        oral evaluations, project work, and classroom\r\n                        participation</strong>. Equal weight is given to a\r\n                        student\'s progress in yoga, sports, music, and\r\n                        character formation — because a report card should\r\n                        reflect the whole child, not just the marks.\r\n                    </p>\r\n                    <p>\r\n                        In <strong>Grade 6, 7, and 8</strong>, students are\r\n                        prepared with structured revision, practice tests, and\r\n                        one-to-one mentoring — building a strong academic base\r\n                        for higher studies. Parents receive regular feedback\r\n                        through <strong>parent-teacher meetings</strong> and\r\n                        written progress reports, so that school and home\r\n                        can work together in the child\'s interest.\r\n                    </p>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n\r\n    <!-- SECTION 6 — CO-CURRICULAR ACTIVITIES -->\r\n    <section class=\"cocurricular-section\">\r\n        <div class=\"container\">\r\n\r\n            <div class=\"cocurricular-heading\">\r\n                <h2 class=\"cocurricular-title\">\r\n                    Co-Curricular <span class=\"orange\">Activities</span>\r\n                </h2>\r\n                <p class=\"cocurricular-sub\">\r\n                    Learning does not stop at the classroom door. Every child —\r\n                    from Grade 1 to Grade 8 — is encouraged to explore,\r\n                    create, and grow beyond books.\r\n                </p>\r\n            </div>\r\n\r\n            <div class=\"cocurricular-grid\">\r\n\r\n                <div class=\"cocurricular-item\">\r\n                    <div class=\"cocurricular-icon\">\r\n                        <i class=\"bi bi-person-arms-up\"></i>\r\n                    </div>\r\n                    <div class=\"cocurricular-body\">\r\n                        <strong>Yoga &amp; Meditation</strong>\r\n                        <span>Daily practice for physical and mental well-being.</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"cocurricular-item\">\r\n                    <div class=\"cocurricular-icon\">\r\n                        <i class=\"bi bi-music-note-beamed\"></i>\r\n                    </div>\r\n                    <div class=\"cocurricular-body\">\r\n                        <strong>Music &amp; Classical Arts</strong>\r\n                        <span>Vocal, instrumental, and classical music training.</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"cocurricular-item\">\r\n                    <div class=\"cocurricular-icon\">\r\n                        <i class=\"bi bi-flower1\"></i>\r\n                    </div>\r\n                    <div class=\"cocurricular-body\">\r\n                        <strong>Bharatanatyam</strong>\r\n                        <span>Classical dance as a form of cultural expression.</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"cocurricular-item\">\r\n                    <div class=\"cocurricular-icon\">\r\n                        <i class=\"bi bi-hand-index-thumb\"></i>\r\n                    </div>\r\n                    <div class=\"cocurricular-body\">\r\n                        <strong>Karate</strong>\r\n                        <span>Self-defence, discipline, and physical confidence.</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"cocurricular-item\">\r\n                    <div class=\"cocurricular-icon\">\r\n                        <i class=\"bi bi-palette\"></i>\r\n                    </div>\r\n                    <div class=\"cocurricular-body\">\r\n                        <strong>Craft &amp; Art</strong>\r\n                        <span>Creativity, imagination, and hands-on skill.</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"cocurricular-item\">\r\n                    <div class=\"cocurricular-icon\">\r\n                        <i class=\"bi bi-trophy-fill\"></i>\r\n                    </div>\r\n                    <div class=\"cocurricular-body\">\r\n                        <strong>Sports &amp; Athletics</strong>\r\n                        <span>Team spirit, fitness, and healthy competition.</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"cocurricular-item\">\r\n                    <div class=\"cocurricular-icon\">\r\n                        <i class=\"bi bi-tree\"></i>\r\n                    </div>\r\n                    <div class=\"cocurricular-body\">\r\n                        <strong>Farming Exposure</strong>\r\n                        <span>Hands-on contact with the dignity of labour.</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"cocurricular-item\">\r\n                    <div class=\"cocurricular-icon\">\r\n                        <i class=\"bi bi-book-half\"></i>\r\n                    </div>\r\n                    <div class=\"cocurricular-body\">\r\n                        <strong>Sanskrit &amp; Heritage</strong>\r\n                        <span>Cultural roots and ancient wisdom.</span>\r\n                    </div>\r\n                </div>\r\n\r\n                <div class=\"cocurricular-item\">\r\n                    <div class=\"cocurricular-icon\">\r\n                        <i class=\"bi bi-people-fill\"></i>\r\n                    </div>\r\n                    <div class=\"cocurricular-body\">\r\n                        <strong>Community Service</strong>\r\n                        <span>Learning to serve the school, the village, and the world.</span>\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </section>\r\n\r\n\r\n    <!-- SECTION 7 — CLOSING QUOTE -->\r\n    <section class=\"curriculum-closing\">\r\n        <div class=\"container\">\r\n            <p>\r\n                Eight years of learning — from the first alphabet in Grade 1\r\n                to the completion of middle school in Grade 8 — designed not\r\n                only to produce good students, but to shape good human\r\n                beings who serve their community, their country, and\r\n                humanity as a whole.\r\n            </p>\r\n            <div class=\"closing-note\">\r\n                Every Child Matters\r\n            </div>\r\n        </div>\r\n    </section>\r\n\r\n</main>', 'Curriculum', '', 'inherit', 'closed', 'closed', '', '36-revision-v1', '', '', '2026-10-13 10:16:54', '2026-10-13 10:16:54', '', 36, 'http://localhost/shree-mahalingeshwara-vidyanikethana-kunjthoor/?p=39', 0, 'revision', '', 0),
